-- AI film & video, Grandmaster tier (days 81-90). Authored content, UNPUBLISHED until a person reviews it in Admin.
insert into public.day
  (track_id, tier_id, day_number, title, objective, lesson_md, skill_focus, assignment_md, rubric,
   est_minutes, is_published, credit_budget, submission_type, ai_evaluate, requires_review)
select t.id, ti.id, v.n, v.title, v.objective, v.lesson_md, v.skill_focus, v.assignment_md, v.rubric,
       v.est_minutes, false, null, v.submission_type, v.ai_evaluate, v.requires_review
from public.track t
join public.tier ti on ti.track_id = t.id and ti.slug = 'grandmaster'
cross join (values
  (81, $t81a$Teach a filmmaking skill$t81a$, $t81b$Explain one skill to a beginner.$t81b$, $t81c$Write a lesson with worked example, practice task and success check.$t81c$, $t81d$Teach a filmmaking skill$t81d$, $t81e$Submit the lesson.$t81e$, $t81f$[{"criterion": "Clear", "max_points": 35, "guidance": "Beginner-friendly."}, {"criterion": "Example", "max_points": 35, "guidance": "Real."}, {"criterion": "Practice", "max_points": 30, "guidance": "Usable."}]$t81f$::jsonb, 60, 'text', false, false),
  (82, $t82a$Critique clinic: three films$t82a$, $t82b$Review three short films.$t82b$, $t82c$Diagnose story, craft and rights in three films: what works, top problem and fix.$t82c$, $t82d$Critique clinic: three films$t82d$, $t82e$Submit three critiques.$t82e$, $t82f$[{"criterion": "Diagnosis", "max_points": 40, "guidance": "Precise."}, {"criterion": "Prioritised", "max_points": 30, "guidance": "Focused."}, {"criterion": "Constructive", "max_points": 30, "guidance": "Kind."}]$t82f$::jsonb, 60, 'text', false, false),
  (83, $t83a$Publish a behind-the-scenes breakdown$t83a$, $t83b$Share your process.$t83b$, $t83c$Show shot by shot how a sequence was made, including failures and costs.$t83c$, $t83d$Publish a behind-the-scenes breakdown$t83d$, $t83e$Submit the breakdown.

**Sharing video:** upload (unlisted) and paste the link. Video is checked by a person.$t83e$, $t83f$[{"criterion": "Process shown", "max_points": 40, "guidance": "Detailed."}, {"criterion": "Failures honest", "max_points": 30, "guidance": "Included."}, {"criterion": "Costs", "max_points": 30, "guidance": "Real."}]$t83f$::jsonb, 60, 'link', false, false),
  (84, $t84a$Case study: a film's results$t84a$, $t84b$Document honestly.$t84b$, $t84c$Goal, process, audience results and lessons.$t84c$, $t84d$Case study: a film's results$t84d$, $t84e$Submit the case study.$t84e$, $t84f$[{"criterion": "Numbers real", "max_points": 40, "guidance": "Honest."}, {"criterion": "Lessons", "max_points": 30, "guidance": "Frank."}, {"criterion": "Clear", "max_points": 30, "guidance": "Structured."}]$t84f$::jsonb, 60, 'text', false, false),
  (85, $t85a$Grandmaster project 1: body-of-work plan$t85a$, $t85b$Plan a visible filmography.$t85b$, $t85c$Deliver a **plan**: point of view, three films, one teaching resource, one breakdown and six-month schedule.

A person reviews your work and can ask for revisions.$t85c$, $t85d$Grandmaster project 1: body-of-work plan$t85d$, $t85e$Submit the plan.$t85e$, $t85f$[{"criterion": "Point of view", "max_points": 30, "guidance": "Distinct."}, {"criterion": "Pieces valuable", "max_points": 30, "guidance": "Strong."}, {"criterion": "Realistic", "max_points": 20, "guidance": "Feasible."}, {"criterion": "Measures", "max_points": 20, "guidance": "Clear."}]$t85f$::jsonb, 90, 'text', false, true),
  (86, $t86a$Mentor a filmmaker$t86a$, $t86b$Review a peer's film.$t86b$, $t86c$Score a peer's film against the rubric with evidence per criterion.$t86c$, $t86d$Mentor a filmmaker$t86d$, $t86e$Submit the scored review.$t86e$, $t86f$[{"criterion": "Justified", "max_points": 40, "guidance": "Evidence."}, {"criterion": "Fair", "max_points": 30, "guidance": "Balanced."}, {"criterion": "Exercise", "max_points": 30, "guidance": "Practical."}]$t86f$::jsonb, 60, 'text', false, false),
  (87, $t87a$Build a course module$t87a$, $t87b$Package your know-how.$t87b$, $t87c$Outcomes, five lessons, tasks, project and rubric; test with a learner.$t87c$, $t87d$Build a course module$t87d$, $t87e$Submit outline, lesson and feedback.$t87e$, $t87f$[{"criterion": "Outcomes", "max_points": 30, "guidance": "Measurable."}, {"criterion": "Lesson", "max_points": 40, "guidance": "Strong."}, {"criterion": "Tested", "max_points": 30, "guidance": "Learner."}]$t87f$::jsonb, 120, 'text', false, false),
  (88, $t88a$Ethics and standards for synthetic media$t88a$, $t88b$State your principles.$t88b$, $t88c$Publish how you use AI, obtain consent, label media and correct mistakes.$t88c$, $t88d$Ethics and standards for synthetic media$t88d$, $t88e$Submit your standards.$t88e$, $t88f$[{"criterion": "Specific", "max_points": 40, "guidance": "Concrete."}, {"criterion": "Accountability", "max_points": 35, "guidance": "Corrections."}, {"criterion": "Labelling", "max_points": 25, "guidance": "Clear."}]$t88f$::jsonb, 60, 'text', false, false),
  (89, $t89a$Impact audit$t89a$, $t89b$Show what your films did.$t89b$, $t89c$Audience, learning shared, opportunities created, with limits.$t89c$, $t89d$Impact audit$t89d$, $t89e$Submit the impact report.$t89e$, $t89f$[{"criterion": "Evidence real", "max_points": 45, "guidance": "Collected."}, {"criterion": "Honest", "max_points": 35, "guidance": "Limits."}, {"criterion": "Next steps", "max_points": 20, "guidance": "Clear."}]$t89f$::jsonb, 60, 'text', false, false),
  (90, $t90a$Grandmaster capstone: portfolio, teaching and impact$t90a$, $t90b$Prove mastery.$t90b$, $t90c$The final assessment. Deliver a **portfolio**: flagship film, breakdown, teaching resource with learner feedback, peer review, standards and impact report.

A person reviews your work and can ask for revisions.$t90c$, $t90d$Grandmaster capstone: portfolio, teaching and impact$t90d$, $t90e$Submit the portfolio and a one-page reflection.

**Sharing video:** upload (unlisted) and paste the link. Video is checked by a person.$t90e$, $t90f$[{"criterion": "Craft and vision", "max_points": 30, "guidance": "Excellent."}, {"criterion": "Rights and honesty", "max_points": 25, "guidance": "Verified."}, {"criterion": "Teaching and mentoring", "max_points": 25, "guidance": "Effective."}, {"criterion": "Impact and reflection", "max_points": 20, "guidance": "Evidenced."}]$t90f$::jsonb, 240, 'link', false, true)
) as v(n, title, objective, lesson_md, skill_focus, assignment_md, rubric, est_minutes, submission_type, ai_evaluate, requires_review)
where t.slug = 'film'
on conflict (track_id, day_number) do nothing;
